// @ts-nocheck
class CryptoHelper{constructor(){this.algo="AES-GCM",this.salt=(new TextEncoder).encode("Nutstore_Internal_Static_Salt")}async deriveKey(t){const e=new TextEncoder,o=await crypto.subtle.importKey("raw",e.encode(t),{name:"PBKDF2"},!1,["deriveKey"]);return crypto.subtle.deriveKey({name:"PBKDF2",salt:this.salt,iterations:1e5,hash:"SHA-256"},o,{name:this.algo,length:256},!1,["encrypt","decrypt"])}async encrypt(t,e){const o=await this.deriveKey(e),r=crypto.getRandomValues(new Uint8Array(12)),a=(new TextEncoder).encode(JSON.stringify(t)),s=await crypto.subtle.encrypt({name:this.algo,iv:r},o,a),n=new Uint8Array(r.byteLength+s.byteLength);return n.set(r,0),n.set(new Uint8Array(s),r.byteLength),this.arrayBufferToBase64(n)}async decrypt(t,e){const o=await this.deriveKey(e),r=this.base64ToArrayBuffer(t),a=r.slice(0,12),s=r.slice(12);try{const t=await crypto.subtle.decrypt({name:this.algo,iv:a},o,s);return JSON.parse((new TextDecoder).decode(t))}catch(t){throw console.log("解密失败:",t),new Error("数据解密失败，可能是密钥不匹配或文件损坏")}}arrayBufferToBase64(t){let e="";const o=new Uint8Array(t);for(let t=0;t<o.byteLength;t++)e+=String.fromCharCode(o[t]);return btoa(e)}base64ToArrayBuffer(t){const e=atob(t),o=e.length,r=new Uint8Array(o);for(let t=0;t<o;t++)r[t]=e.charCodeAt(t);return r}}class NutstoreSync{constructor(){this.config={baseURL:"https://dav.jianguoyun.com/dav",appFolder:"AI对话收藏"},this.crypto=new CryptoHelper,this.INTERNAL_SECRET="NutstoreSync_HTMLElement"}async getAuthHeader(){const t=await chrome.storage.local.get("nutstore_credentials");if(!t.nutstore_credentials)throw new Error("未登录");return`Basic ${t.nutstore_credentials}`}async ensureFolderExists(){const t=await this.getAuthHeader(),e=this.config.appFolder,o=await fetch(`${this.config.baseURL}/${e}/`,{method:"PROPFIND",headers:{Authorization:t,Depth:"0"}});if(404===o.status)throw new Error(`文件夹 "${e}" 不存在，请在坚果云网页端创建`);return o.ok}async uploadKey(t,e,o){try{const r=await this.getAuthHeader(),a=`${this.config.appFolder}/${t}.json`,s={value:await this.crypto.encrypt(e,this.INTERNAL_SECRET),encrypted:!0,_syncMeta:{lastModified:o,key:t}},n=await fetch(`${this.config.baseURL}/${a}`,{method:"PUT",headers:{Authorization:r,"Content-Type":"application/json"},body:JSON.stringify(s,null,2)});if(!n.ok){const e=await n.text();throw new Error(`上传 ${t} 失败: ${n.status} ${e}`)}return console.log(`✅ 成功上传 (已加密): ${t}`),{success:!0,key:t}}catch(e){throw console.log(`上传键 ${t} 错误:`,e),e}}async downloadKey(t){try{const e=await this.getAuthHeader(),o=`${this.config.appFolder}/${t}.json`,r=await fetch(`${this.config.baseURL}/${o}`,{method:"GET",headers:{Authorization:e}});if(404===r.status)return null;if(!r.ok){const e=await r.text();throw new Error(`下载 ${t} 失败: ${r.status} ${e}`)}const a=await r.json();if(!0===a.encrypted)try{return await this.crypto.decrypt(a.value,this.INTERNAL_SECRET)}catch(e){throw console.log(`文件 ${t} 解密失败`,e),new Error("云端文件损坏或版本不兼容")}return console.log(`[Sync] 读取到旧版明文文件: ${t}`),a.value}catch(e){throw console.log(`下载键 ${t} 错误:`,e),e}}async listRemoteFiles(){try{const t=await this.getAuthHeader(),e=this.config.appFolder,o=await fetch(`${this.config.baseURL}/${e}/`,{method:"PROPFIND",headers:{Authorization:t,Depth:"1"}});if(!o.ok)throw new Error(`获取文件列表失败: ${o.status}`);const r=await o.text(),a=[],s=/<d:response>([\s\S]*?)<\/d:response>/g,n=r.matchAll(s);for(const t of n){const e=t[1],o=e.match(/<d:href>([^<]+)<\/d:href>/);if(!o)continue;const r=decodeURIComponent(o[1]).split("/").pop();if(!r||!r.endsWith(".json")||e.includes("<d:collection/>"))continue;const s=e.match(/<d:getlastmodified>([^<]+)<\/d:getlastmodified>/i),n=s?new Date(s[1]).getTime():Date.now(),i=e.match(/<d:getetag>([^<]+)<\/d:getetag>/i),c=i?i[1].replace(/"/g,""):"";a.push({key:r.replace(".json",""),lastModified:n,etag:c})}return a}catch(t){throw console.log("[listRemoteFiles] 致命错误:",t),new Error(`无法解析云端文件列表: ${t.message}`)}}async checkKeyVersion(t){try{const e=await this.getAuthHeader(),o=`${this.config.appFolder}/${t}.json`,r=await fetch(`${this.config.baseURL}/${o}`,{method:"HEAD",headers:{Authorization:e}});if(!r.ok)return null;const a=r.headers.get("Last-Modified"),s=r.headers.get("ETag");return{key:t,lastModified:new Date(a).getTime(),etag:s}}catch(e){return console.log(`检查键 ${t} 版本错误:`,e),null}}async deleteKey(t){try{const e=await this.getAuthHeader(),o=`${this.config.appFolder}/${t}.json`,r=await fetch(`${this.config.baseURL}/${o}`,{method:"DELETE",headers:{Authorization:e}});if(!r.ok&&404!==r.status){const t=await r.text();throw new Error(`删除失败: ${r.status} ${t}`)}return console.log(`✓ 已删除云端文件: "${t}"`),{success:!0,key:t}}catch(e){throw console.log(`删除键 ${t} 错误:`,e),e}}}